catalog_script_client.script:
function onSubmit() {
    //Type appropriate comment here, and begin script below
    var url = top.location.href;
    var ritm_id = new URLSearchParams(url).get("sysparm_ritm_id");
    if (!ritm_id) {
        return;
    }
    // 获取页面变量值
    var requested_for = g_form.getValue('requested_for');
    var computer_model = g_form.getValue('computer_model');
    var notes = g_form.getValue('notes');
    // 调用Ajax 更新request item的值
    var ga = new GlideAjax('ResubmitRITMUtils');
    ga.addParam('sysparm_name', 'updateRITM');
    ga.addParam('sysparm_ritm_id', ritm_id);
    ga.addParam('sysparm_requested_for', requested_for);
    ga.addParam('sysparm_computer_model', computer_model);
    ga.addParam('sysparm_notes', notes);
    ga.getXMLAnswer(function(response) {
		var data = JSON.parse(response);
        if (data.status === 'ok') {
            alert("重新提交成功！");
            // 跳转到 request 页面
			top.location.href = '/sp?id=sc_request&is_new_order=true&table=sc_request&sys_id=' + data.req_id;
        } else {
            alert("提交失败：" + response);
        }
    });
    return false; // 阻止原有Catalog item提交
}
